import { SetMetadata } from '@nestjs/common';

export const IS_PUBLIC_KEY = 'isPublic';
export const Public = () => SetMetadata(IS_PUBLIC_KEY, true);
```

## 2. Write the guard so it checks the metadata

```ts
// src/auth/jwt-auth.guard.ts
import { CanActivate, ExecutionContext, Injectable } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { IS_PUBLIC_KEY } from './public.decorator';

@Injectable()
export class JwtAuthGuard implements CanActivate {
  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) {
      return true;
    }
    // ...verify the JWT here (or delegate to a Passport/JWT strategy)
  }
}
```

Using `getAllAndOverride` lets you mark either a whole controller or a single method as public.

## 3. Register it globally as an `APP_GUARD` provider

In your root (or auth) module:

```ts
import { Module } from '@nestjs/common';
import { APP_GUARD } from '@nestjs/core';

@Module({
  providers: [
    { provide: APP_GUARD, useClass: JwtAuthGuard },
  ],
})
export class AppModule {}
```

## Why the `APP_GUARD` token and not `app.useGlobalGuards()`

The `APP_*` token form registers the guard **inside Nest's own DI graph**, so it can inject other providers — here, `Reflector`, and in a fuller setup a `JwtService`, `UsersService`, etc. `app.useGlobalGuards(new JwtAuthGuard())` on the bootstrapped instance bypasses DI and can't inject anything.

## 4. Mark the exceptions

Any endpoint that should stay open just gets the decorator — on the method or the whole controller:

```ts
@Public()
@Post('login')
login(@Body() dto: LoginDto) { /* ... */ }
```

## The key reason to do it this way

This **fails safe**. Every new controller anyone adds later is protected by default, and the only way to open one is a deliberate `@Public()` annotation that shows up in a diff. If instead you decorate controllers one by one with `@UseGuards(JwtAuthGuard)`, a newly added controller silently starts out unprotected — the exact failure mode you want to avoid.

## Verification before calling it done

- `nest build` and `tsc --noEmit` both exit 0.
- The app boots with no `UnknownDependenciesException` — a common cause here is forgetting that `JwtAuthGuard` now needs `Reflector` (and whatever strategy service it depends on) available in the module that provides it.
- Confirm both directions actually work: a request to a normal route without a token is rejected, and a request to a `@Public()` route goes through with no token. Don't assume the decorator wiring is correct just because it compiles.

Register the guard globally via the `APP_GUARD` provider token, have it check for an opt-out decorator using `Reflector`, and decorate the public endpoints with that decorator. Global-by-default with explicit opt-out fails safe: any controller someone adds later is protected automatically, instead of silently public because they forgot the decorator.

**1. Mark public routes with a metadata decorator**

```ts
// src/auth/public.decorator.ts
import { SetMetadata } from '@nestjs/common';

export const IS_PUBLIC_KEY = 'isPublic';
export const Public = () => SetMetadata(IS_PUBLIC_KEY, true);
```

**2. Have the guard read that metadata**

```ts
// src/auth/jwt-auth.guard.ts
import {
  CanActivate,
  ExecutionContext,
  Injectable,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { JwtService } from '@nestjs/jwt';
import { IS_PUBLIC_KEY } from './public.decorator';

@Injectable()
export class JwtAuthGuard implements CanActivate {
  constructor(
    private readonly jwtService: JwtService,
    private readonly reflector: Reflector,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) {
      return true;
    }

    const request = context.switchToHttp().getRequest();
    const header: string | undefined = request.headers['authorization'];
    const token = header?.startsWith('Bearer ') ? header.slice(7) : undefined;
    if (!token) {
      throw new UnauthorizedException();
    }

    try {
      request.user = await this.jwtService.verifyAsync(token);
      return true;
    } catch {
      throw new UnauthorizedException();
    }
  }
}
```

`getAllAndOverride` checks the handler first, then the class, so a decorator on a single method wins over one on the controller.

**3. Register it as an APP_GUARD, not `useGlobalGuards`**

```ts
// src/auth/auth.module.ts
import { Module } from '@nestjs/common';
import { APP_GUARD } from '@nestjs/core';
import { JwtModule } from '@nestjs/jwt';
import { JwtAuthGuard } from './jwt-auth.guard';

@Module({
  imports: [JwtModule.register({ secret: process.env.JWT_SECRET })],
  providers: [
    {
      provide: APP_GUARD,
      useClass: JwtAuthGuard,
    },
  ],
})
export class AuthModule {}
```

The `APP_GUARD` token keeps the guard inside Nest's own DI graph, so it can inject `Reflector` and `JwtService` the way it does above. `app.useGlobalGuards(new JwtAuthGuard())` runs the instance you construct there, outside the container — so those constructor injections don't resolve and you end up hand-wiring dependencies.

**4. Opt individual endpoints out**

```ts
// src/users/users.controller.ts
import { Controller, Get } from '@nestjs/common';
import { Public } from '../auth/public.decorator';

@Controller('users')
export class UsersController {
  @Public()
  @Get('health')
  health() {
    return { status: 'ok' };
  }

  @Get('me')
  me() {
    // reaches here only with a valid token
  }
}
```

**Two things worth calling out**

Ordering: a global guard registered with `APP_GUARD` runs before controller-level `@UseGuards` but after middleware. If you later need a guard that must run before auth (say, a rate limiter keyed by IP rather than user), register that as a separate `APP_GUARD` too — Nest runs multiple global guards in the order their providers are registered.

Composition with roles: don't fold role checks into the JWT guard. Keep `JwtAuthGuard` doing authentication only, then add a second `RolesGuard` registered globally after it, reading a `@Roles(...)` metadata key. That guard should return `true` early when the route is `@Public()` or carries no roles metadata, so the two guards compose instead of fighting each other.

Before calling this done: confirm the app boots with no `UnknownDependenciesException` from the guard's injections, and hit one protected and one `@Public()` route to verify the opt-out actually takes effect.

# Global JWT guard with opt-out public routes

The right shape is a **global guard registered through the DI graph** plus a **`SetMetadata`-backed opt-out decorator** read via `Reflector`. That way every route is protected by default and adding a new controller can never accidentally leave it open — a future endpoint only becomes public if someone deliberately marks it.

## 1. Mark public routes with a custom decorator

```ts
// src/auth/public.decorator.ts
import { SetMetadata } from '@nestjs/common';

export const IS_PUBLIC_KEY = 'isPublic';
export const Public = () => SetMetadata(IS_PUBLIC_KEY, true);
```

## 2. Read it in the guard

```ts
// src/auth/jwt-auth.guard.ts
import {
  CanActivate, ExecutionContext, Injectable, UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { JwtService } from '@nestjs/jwt';
import { IS_PUBLIC_KEY } from './public.decorator';

@Injectable()
export class JwtAuthGuard implements CanActivate {
  constructor(
    private readonly reflector: Reflector,
    private readonly jwtService: JwtService,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) return true;

    const req = context.switchToHttp().getRequest();
    const token = req.headers.authorization?.replace(/^Bearer\s+/i, '');
    if (!token) throw new UnauthorizedException();

    try {
      req.user = await this.jwtService.verifyAsync(token);
      return true;
    } catch {
      throw new UnauthorizedException();
    }
  }
}
```

`getAllAndOverride` checks the handler first, then the class, so `@Public()` can sit on a single method or on a whole controller.

## 3. Register it globally as an `APP_GUARD`

```ts
// src/auth/auth.module.ts
import { Module } from '@nestjs/common';
import { APP_GUARD } from '@nestjs/core';
import { JwtModule } from '@nestjs/jwt';
import { JwtAuthGuard } from './jwt-auth.guard';
import { AuthController } from './auth.controller';

@Module({
  imports: [JwtModule.register({ secret: process.env.JWT_SECRET })],
  controllers: [AuthController],
  providers: [
    { provide: APP_GUARD, useClass: JwtAuthGuard },
  ],
})
export class AuthModule {}
```

The `APP_GUARD` token form is the key detail: it registers the guard inside Nest's own DI graph, so the guard can inject `Reflector`, `JwtService`, a `UsersService`, etc. `app.useGlobalGuards(new JwtAuthGuard())` would **not** — that instance is constructed outside DI and cannot inject anything.

## 4. Opt out on the endpoints that should stay open

```ts
@Controller('auth')
export class AuthController {
  @Public()
  @Post('login')
  login(@Body() dto: LoginDto) { /* ... */ }

  @Public()
  @Post('register')
  register(@Body() dto: RegisterDto) { /* ... */ }

  @Get('me')           // protected by default, no decorator needed
  me(@Req() req) { return req.user; }
}
```

You can also mark a whole controller public with `@Public()` at the class level and re-protect individual methods if needed — the handler-level metadata wins.

## Why this over the alternatives

- **Per-controller `@UseGuards(JwtAuthGuard)`** means a new controller added six months from now is unprotected until someone remembers. A global guard fails *closed*.
- **`app.useGlobalGuards(...)`** works for a guard with no dependencies, but as soon as the guard needs `Reflector` or your `JwtService` you're stuck — and most real auth guards need both.
- **A middleware instead of a guard** runs before the route metadata is easily reachable and doesn't compose with `@Public()` cleanly; `Reflector` is designed for exactly this.

## Verification before you call it done

- App boots with no `UnknownDependenciesException` — the guard resolved `Reflector` and `JwtService` from DI.
- A protected route returns 401 without a token and 200 with a valid one.
- Each `@Public()` route returns its normal response **without** a token.
- `tsc --noEmit` / `nest build` exit 0.
- Grep the routes you intended to be public and confirm each one carries `@Public()` — don't rely on "I think I marked it."

No — that's exactly the trap this skill's rules warn about, and injecting it as-is will silently break the singleton.

## Why it's not fine

Nest propagates provider scope **up** the injection graph, not down. If `UsersService` depends on a `REQUEST`-scoped provider, `UsersService` cannot stay a Singleton: Nest must instantiate a fresh `UsersService` for every incoming request in order to give it a fresh request-scoped dependency. So:

- `UsersService` effectively becomes request-scoped whether you declared it that way or not.
- Everything that injects `UsersService` (controllers, other services, and anything that injects *those*) gets dragged into per-request instantiation too — the scope propagates transitively.
- For a service "used all over the app," that means the whole subtree is rebuilt on every request: per-request allocation and GC pressure, lost cross-request caching/memoization, and any `OnModuleInit` lifecycle work re-running per request instead of once at boot.
- Depending on how it's wired, you may instead get a resolution-time error rather than a silent behavior change — either outcome is a real bug, and the silent one is worse because tests that don't exercise concurrency won't catch it.

The rule is direct: **never inject a `REQUEST`-scoped or `TRANSIENT` provider into a Singleton provider** unless you have deliberately decided that the Singleton's scope should change. For a service this widely used, you almost certainly have not.

## What to do instead

Pick based on what actually needs the current user:

**1. Pass the user in as a method argument (usually the right answer).**
Keep the request-scoped provider at the edge (controller or a thin request-scoped helper) and hand the resolved user — or just the id — into the singleton as a plain parameter:

```ts
// request-scoped provider stays at the edge
@Injectable({ scope: Scope.REQUEST })
export class RequestUserProvider {
  constructor(@Inject(REQUEST) private readonly req: Request) {}
  get currentUser(): AuthenticatedUser { /* read off req */ }
}

// singleton stays a singleton
@Injectable()
export class UsersService {
  findForUser(userId: string) { /* ... */ }
}

@Controller('users')
export class UsersController {
  constructor(
    private readonly currentUser: RequestUserProvider,
    private readonly users: UsersService,
  ) {}

  @Get('me')
  me() {
    return this.users.findForUser(this.currentUser.currentUser.id);
  }
}
```

The scope change is confined to the controller/edge, and `UsersService` remains a true singleton. This is also easier to test — call `findForUser('u1')` directly with no HTTP stack.

**2. Use `@Inject(REQUEST)` only where the request is genuinely needed**, not as a transitive dependency of a shared service.

**3. If you truly want request-scoped semantics in a singleton, use `AsyncLocalStorage`** (e.g. `nestjs-cls` or a small `AsyncLocalStorage`-backed context provider) rather than `Scope.REQUEST`. It gives you per-request context without re-instantiating the injection subtree per request.

**4. Only accept the scope change if you actually mean it** — i.e. you've decided `UsersService` should be request-scoped, you're aware of the cost, and you're not surprised that its consumers become request-scoped too. That's a rare, deliberate choice for a service "used all over the app."

## Bottom line

Don't inject the request-scoped provider into the singleton as-is. Introduce it at the controller/edge and pass the resolved user or id down into `UsersService` as a normal argument — or switch to `AsyncLocalStorage`-based context if you need ambient per-request access deep in the call stack. Either way, verify by booting the app and checking there's no scope-propagation surprise and that `UsersService` is still instantiated once at startup, not once per request.

# Unit-testing `UsersService` with a mocked `UsersRepository`

Because you're testing one provider in isolation, don't import `UsersModule`. Hand-assemble the providers array and declare the mock repository directly — no `overrideProvider` needed, since you already control the whole list.

## Setup

```typescript
// users.service.spec.ts
import { Test, TestingModule } from '@nestjs/testing';
import { UsersService } from './users.service';
import { UsersRepository } from './users.repository';

describe('UsersService', () => {
  let service: UsersService;
  let repo: jest.Mocked<UsersRepository>; // or whatever mock type fits your repo

  beforeEach(async () => {
    const mockRepo = {
      findById: jest.fn(),
      save: jest.fn(),
      // ...only the methods UsersService actually calls
    };

    const moduleRef: TestingModule = await Test.createTestingModule({
      providers: [
        UsersService,
        { provide: UsersRepository, useValue: mockRepo },
      ],
    }).compile();

    service = moduleRef.get(UsersService);
    repo = moduleRef.get(UsersRepository);
  });

  it('returns the user from the repository', async () => {
    repo.findById.mockResolvedValue({ id: '1', name: 'Ada' });

    await expect(service.findOne('1')).resolves.toEqual({ id: '1', name: 'Ada' });
  });

  it('throws NotFoundException when the repository returns null', async () => {
    repo.findById.mockResolvedValue(null);

    await expect(service.findOne('1')).rejects.toThrow(NotFoundException);
  });
});
```

## The rules that matter here

- **Build through the testing module, not `new`.** `Test.createTestingModule(...).compile()` is what proves `UsersService`'s constructor actually resolves against the provider token you registered. `new UsersService(mockRepo)` skips that wiring and can pass while the real module would fail to compile. (Nest's own docs do show `new` for pure logic, but use the testing module when you want the DI graph exercised.)
- **Mock at the injected boundary** — the repository methods — not a private method on `UsersService`. Stubbing `service['somePrivateHelper']` couples the test to an implementation detail.
- **Assert on behavior**, not on `repo.findById` being called N times as the whole test. The call-count check is fine as a supporting assertion, but the test should pin down the service's return value or the exception it throws.
- **Pick one technique per provider.** Either declare the mock in the providers array (this case) *or* `.overrideProvider(UsersRepository).useValue(...)` when you're importing a real module you don't want to reassemble — never both for the same token.

## What you don't need here

No `createNestApplication()`, no supertest, no `app.close()` — those belong to e2e specs that drive the real HTTP pipeline through guards/pipes/filters. For a single-provider unit test, `moduleRef.get(UsersService)` and direct method calls are the whole story.

If `UsersService` has other injected dependencies, add a mock entry for each one in `providers`; a missing one will surface as a compile-time "Nest can't resolve dependencies" error, which is exactly the signal that the module graph isn't complete.

Build the test through `Test.createTestingModule` with the mock declared directly in the `providers` array — you control the whole list, so no `.overrideProvider()` is needed:

```typescript
import { Test, TestingModule } from '@nestjs/testing';
import { UsersService } from './users.service';
import { UsersRepository } from './users.repository';

describe('UsersService', () => {
  let service: UsersService;
  let repo: { findById: jest.Mock };

  beforeEach(async () => {
    repo = {
      findById: jest.fn(),
    };

    const moduleRef: TestingModule = await Test.createTestingModule({
      providers: [
        UsersService,
        { provide: UsersRepository, useValue: repo },
      ],
    }).compile();

    service = moduleRef.get(UsersService);
  });

  it('returns the user when the repo finds one', async () => {
    const user = { id: '1', name: 'Ada' };
    repo.findById.mockResolvedValue(user);

    await expect(service.findById('1')).resolves.toEqual(user);
    expect(repo.findById).toHaveBeenCalledWith('1');
  });

  it('throws when the repo returns null', async () => {
    repo.findById.mockResolvedValue(null);

    await expect(service.findById('1')).rejects.toThrow();
  });
});
```

Key points, tied to the workflow:

1. **Mock the boundary, not the internals.** `UsersRepository` is the injected dependency — replace it with `{ provide: UsersRepository, useValue: mockRepo }`. Do *not* stub a private method on `UsersService` that happens to call the repo.

2. **Use `{ provide: UsersRepository, useValue: ... }` (or `useFactory`)** rather than `.overrideProvider()` here. `.overrideProvider()` exists to swap one provider inside a real module you're importing wholesale (`imports: [UsersModule]`). Since you're declaring the providers yourself, the mock *is* the provider — no override step.

3. **Resolve the instance with `moduleRef.get(UsersService)`.** Don't write `new UsersService(mockRepo)`; that bypasses the DI graph you just assembled.

4. **Assert on behavior, not call counts alone.** Check the resolved value / thrown exception (`expect(repo.findById).toHaveBeenCalledWith(...)` is a fine *supplement*, but the return value or rejection is the real assertion).

5. **Recreate the module (and reset mocks) in `beforeEach`** so specs don't leak state into each other. `jest.fn()` fresh each time handles the reset; if you reuse a mock object across tests, call `mockClear()`/`mockReset()` in `beforeEach` or `afterEach`.

6. **If the dependency is something other than a class** (e.g. a config injection token or an HTTP client provided via a custom token), provide it with that same token string/symbol so Nest can match it.

That's the entirety of the setup — compile once per test with the mock in the provider list, grab the service via `get()`, and drive it through its public methods.

Use `Test.createTestingModule` with a provider that supplies a double for the repository, compiling only the providers you actually need. Both of these are correct and idiomatic — pick based on what you control:

**Hand-assembled providers array (usual choice for a focused unit test):**

```typescript
import { Test, TestingModule } from '@nestjs/testing';
import { UsersService } from './users.service';
import { UsersRepository } from './users.repository';

describe('UsersService', () => {
  let service: UsersService;
  let repo: { findById: jest.Mock; save: jest.Mock };

  beforeEach(async () => {
    repo = {
      findById: jest.fn(),
      save: jest.fn(),
    };

    const moduleRef: TestingModule = await Test.createTestingModule({
      providers: [
        UsersService,
        { provide: UsersRepository, useValue: repo },
      ],
    }).compile();

    service = moduleRef.get(UsersService);
  });

  it('returns the user from the repository', async () => {
    const user = { id: 1, name: 'Ada' };
    repo.findById.mockResolvedValue(user);

    await expect(service.findOne(1)).resolves.toEqual(user);
    expect(repo.findById).toHaveBeenCalledWith(1);
  });

  it('throws when the user is missing', async () => {
    repo.findById.mockResolvedValue(null);
    await expect(service.findOne(1)).rejects.toThrow();
